"""Crash sweep: for every RELAY_FAULT=write:N / commit:N, sink up and down,
run a create/start/complete/cancel-rejected/create-j2/cancel-j2 sequence,
then restart with the sink up, pump, and check invariants."""
import json, os, subprocess, sys, tempfile, shutil, sqlite3

REPO = os.environ["RELAY_REPO"]
CHILD = os.path.join(os.path.dirname(__file__), "child.py")

SEQ = [
    {"command_id": "c1", "type": "create", "job_id": "j1", "payload": {}},
    {"command_id": "c2", "type": "start", "job_id": "j1", "payload": {}},
    {"command_id": "c3", "type": "complete", "job_id": "j1", "payload": {}},
    {"command_id": "c4", "type": "cancel", "job_id": "j1", "payload": {}},   # rejected
    {"command_id": "c5", "type": "create", "job_id": "j2", "payload": {}},
    {"command_id": "c6", "type": "start", "job_id": "j2", "payload": {}},
    {"command_id": "c7", "type": "cancel", "job_id": "j2", "payload": {}},
    "PUMP",
]


def run(db, sink, lines, fault=None, up=True):
    env = {k: v for k, v in os.environ.items() if k != "RELAY_FAULT"}
    if fault:
        env["RELAY_FAULT"] = fault
    p = subprocess.run(
        [sys.executable, CHILD, db, sink, "up" if up else "down"],
        input="\n".join(json.dumps(l) if isinstance(l, dict) else l for l in lines) + "\n",
        capture_output=True, text=True, env=env,
    )
    outs = [json.loads(l) for l in p.stdout.splitlines() if l.strip()]
    return p.returncode, outs, p.stderr


def read_sink(path):
    if not os.path.exists(path):
        return []
    with open(path) as f:
        return [json.loads(l) for l in f if l.strip()]


def read_db(db):
    c = sqlite3.connect(db)
    events = c.execute("SELECT seq,event_id,job_id,type,state FROM events ORDER BY seq").fetchall()
    jobs = dict(c.execute("SELECT job_id,state FROM jobs").fetchall())
    outbox = [r[0] for r in c.execute("SELECT event_id FROM outbox").fetchall()]
    cmds = dict(c.execute("SELECT command_id, result FROM commands").fetchall())
    c.close()
    return events, jobs, outbox, cmds


def check(label, db, sink, crashed_sink):
    """Invariants after crash+restart+pump."""
    problems = []
    events, jobs, outbox, cmds = read_db(db)
    ev_ids = [e[1] for e in events]
    # 1. never announced an uncommitted event (checked at crash time and after)
    for s in crashed_sink:
        if s["event_id"] not in ev_ids:
            problems.append(f"announced uncommitted event at crash time: {s}")
    final_sink = read_sink(sink)
    for s in final_sink:
        if s["event_id"] not in ev_ids:
            problems.append(f"announced uncommitted event: {s}")
    # 2. every committed event announced at least once
    seen = {s["event_id"] for s in final_sink}
    for e in events:
        if e[1] not in seen:
            problems.append(f"committed event never announced: {e}")
    # 3. outbox drained
    if outbox:
        problems.append(f"outbox not drained: {outbox}")
    # 4. job state == last event state per job
    last = {}
    for e in events:
        last[e[2]] = e[4]
    if last != jobs:
        problems.append(f"jobs {jobs} != implied {last}")
    # 5. per-job order of first announcements matches log order
    for job in last:
        log_order = [e[1] for e in events if e[2] == job]
        first_seen = []
        for s in final_sink:
            if s["job_id"] == job and s["event_id"] not in first_seen:
                first_seen.append(s["event_id"])
        if first_seen != log_order:
            problems.append(f"job {job} announce order {first_seen} != log {log_order}")
    # 6. every event has a command record and vice-versa for ok results
    for e in events:
        pass
    for cid, res in cmds.items():
        r = json.loads(res)
        if r["ok"] and r["event_id"] not in ev_ids:
            problems.append(f"command {cid} recorded ok with event not in log")
    return problems


def scenario(fault, up):
    d = tempfile.mkdtemp(prefix="relay_sweep_")
    db, sink = os.path.join(d, "relay.db"), os.path.join(d, "sink.jsonl")
    rc, outs, err = run(db, sink, SEQ, fault=fault, up=up)
    crashed_sink = read_sink(sink)
    crashed = rc == 137
    # restart: replay the whole command sequence (callers retry) then pump
    rc2, outs2, err2 = run(db, sink, SEQ, up=True)
    if rc2 != 0:
        return crashed, [f"restart rc={rc2} stderr={err2[-300:]}"]
    problems = check(f"{fault}/{up}", db, sink, crashed_sink)
    # expected final results after replay
    exp = ["queued", "running", "succeeded", None, "queued", "running", "cancelled"]
    for o, e in zip(outs2[:7], exp):
        if e is None:
            if o != {"ok": False, "error": "INVALID_TRANSITION"}:
                problems.append(f"c4 expected INVALID_TRANSITION got {o}")
        elif not (o.get("ok") and o.get("state") == e):
            problems.append(f"replay result {o} expected state {e}")
    # results returned before the crash must equal the replayed ones
    for i, o in enumerate(outs):
        if i < 7 and o != outs2[i]:
            problems.append(f"pre-crash result #{i} {o} != post-restart replay {outs2[i]}")
    shutil.rmtree(d)
    return crashed, problems


if __name__ == "__main__":
    total = 0
    bad = 0
    for up in (True, False):
        for kind, rng in (("write", range(1, 40)), ("commit", range(1, 25))):
            for n in rng:
                fault = f"{kind}:{n}"
                crashed, problems = scenario(fault, up)
                total += 1
                if not crashed:
                    print(f"[no crash] {fault} up={up}")  # beyond sequence length
                    if problems:
                        print("   ", problems)
                    break
                if problems:
                    bad += 1
                    print(f"[FAIL] {fault} up={up}: {problems}")
    print(f"scenarios={total} failures={bad}")
